def clean(df):
    df['body_mass_g'] = df['body_mass_g'].str.replace(',', '').astype(float)
    df = df[df['flipper_length_mm'] >= 0]
    df['sex'] = df['sex'].str.strip()
    return df

def answer(df):
    total_body_mass = df.groupby('species')['body_mass_g'].sum().reset_index()
    result = total_body_mass.set_index('species')['body_mass_g'].to_dict()
    return result}
